factorial.code:
fprintf('%d\n', fact(10));

% A local function, placed after the script code
function r = fact(n)
    if n <= 1
        r = 1;
    else
        r = n * fact(n - 1);
    end
end

signature.code:
% Solve A*x = b with backslash: Gaussian elimination, no inverse, no loops
A = [2 1 -1; -3 -1 2; -2 1 2];
b = [8; -11; -3];
x = A \ b;
fprintf('x = %g %g %g\n', x);

% * is the matrix product, .* multiplies element by element
n = 1:4;                   % the colon operator makes a row vector
T = n' * n;                % column times row: a 4-by-4 multiplication table
fprintf('%2d %2d %2d %2d\n', T);
fprintf('n.*n = %s\n', mat2str(n .* n));

% Whole-array arithmetic, end indexing and logical masks replace loops
t = 0:0.5:3;               % start:step:stop
y = t.^2 - 2*t;
fprintf('last two: %s\n', mat2str(y(end-1:end)));
fprintf('negative at t = %s\n', mat2str(t(y < 0)));
y(y < 0) = 0;              % assign through the mask
fprintf('clamped: %s\n', mat2str(y));
